GUARD.fingerprintAlgorithmExpression:
(slide) => {
  const normalize = (v) => {
    if (v === null || v === undefined) return null;
    if (v === figma.mixed) return "$mixed";
    if (typeof v === "number") return Number.isFinite(v) ? v : null;
    if (typeof v === "string" || typeof v === "boolean") return v;
    if (typeof v === "symbol") return "$symbol:" + String(v);
    if (Array.isArray(v)) return v.map(normalize);
    if (typeof v === "object") {
      const out = {};
      for (const key of Object.keys(v).sort()) out[key] = normalize(v[key]);
      return out;
    }
    return null;
  };
  let hash = 0x811c9dc5;
  const byte = (b) => { hash = Math.imul(hash ^ b, 0x01000193) >>> 0; };
  const utf8 = (s) => {
    for (let i = 0; i < s.length; i++) {
      let cp = s.codePointAt(i);
      if (cp > 0xffff) i++;
      else if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
      if (cp <= 0x7f) byte(cp);
      else if (cp <= 0x7ff) { byte(0xc0 | (cp >> 6)); byte(0x80 | (cp & 63)); }
      else if (cp <= 0xffff) { byte(0xe0 | (cp >> 12)); byte(0x80 | ((cp >> 6) & 63)); byte(0x80 | (cp & 63)); }
      else { byte(0xf0 | (cp >> 18)); byte(0x80 | ((cp >> 12) & 63)); byte(0x80 | ((cp >> 6) & 63)); byte(0x80 | (cp & 63)); }
    }
  };
  const value = (n, key) => key in n ? n[key] : null;
  const visit = (n) => {
    const text = n.type === "TEXT";
    const opaque = n.type === "SLIDE_GRID" || n.type === "SLIDE_ROW";
    let fills = opaque ? null : value(n, "fills");
    let fontSize = text ? n.fontSize : null;
    let fontName = text ? n.fontName : null;
    if (text && (fontSize === figma.mixed || fontName === figma.mixed || fills === figma.mixed)) {
      const fields = ["fontSize", "fontName", "fills"].filter(key => value(n, key) === figma.mixed);
      const segments = n.getStyledTextSegments(fields);
      const mixed = (key) => ({mixed: true, segments: segments.map(s => [s.start, s.end, s[key]])});
      if (fontSize === figma.mixed) fontSize = mixed("fontSize");
      if (fontName === figma.mixed) fontName = mixed("fontName");
      if (fills === figma.mixed) fills = mixed("fills");
    }
    const record = [n.id, n.type, n.name, value(n, "x"), value(n, "y"), value(n, "width"), value(n, "height"), text ? n.characters : null, fontSize, fontName, fills];
    utf8(JSON.stringify(normalize(record)) + "\n");
